// A pretend remote API. Every function uses Node-style callbacks:
//   callback(error, result)
// Do not edit this file. The tests always use their own copy.

const USERS = { 1: { id: 1, name: "Ada" }, 2: { id: 2, name: "Alan" } };
const ORDERS = {
  1: [{ productId: "p1", qty: 2 }, { productId: "p3", qty: 1 }],
  2: [],
};
const PRODUCTS = {
  p1: { id: "p1", title: "Keyboard", price: 50 },
  p2: { id: "p2", title: "Mouse", price: 20 },
  p3: { id: "p3", title: "Monitor", price: 180 },
};

function later(fn) {
  setTimeout(fn, Math.random() * 5);
}

export function getUser(id, callback) {
  later(() => (USERS[id] ? callback(null, USERS[id]) : callback(new Error(`no user ${id}`))));
}

export function getOrders(userId, callback) {
  later(() => callback(null, ORDERS[userId] ?? []));
}

export function getProduct(id, callback) {
  later(() => (PRODUCTS[id] ? callback(null, PRODUCTS[id]) : callback(new Error(`no product ${id}`))));
}
